void qux_interrupts_array_deinit(int unit)
{
    soc_interrupt_db_t *qux_interrupts;
    soc_interrupt_tree_t *qux_interrupt_tree;
    int inter = 0;
    SOCDNX_INIT_FUNC_DEFS;

    
    if(NULL == SOC_CONTROL(unit)->interrupts_info) {
        SOC_EXIT;
    }

    qux_interrupts = SOC_CONTROL(unit)->interrupts_info->interrupt_db_info;
    qux_interrupt_tree = SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info;

    for (inter = 0; inter < QUX_INT_LAST ; inter++) {
        if (qux_interrupts[inter].statistics_count != NULL) {
            sal_free(qux_interrupts[inter].statistics_count);
            qux_interrupts[inter].statistics_count = NULL;
        }
        if (qux_interrupts[inter].storm_nominal_count != NULL) {
            sal_free(qux_interrupts[inter].storm_nominal_count);
            qux_interrupts[inter].storm_nominal_count = NULL;
        }       
        if (qux_interrupts[inter].storm_detection_occurrences != NULL) {
            sal_free(qux_interrupts[inter].storm_detection_occurrences);
            qux_interrupts[inter].storm_detection_occurrences = NULL;
        }
        if (qux_interrupts[inter].storm_detection_start_time != NULL) {
            sal_free(qux_interrupts[inter].storm_detection_start_time);
            qux_interrupts[inter].storm_detection_start_time = NULL;
        }
    }

    if (qux_interrupts != NULL) {
        sal_free(qux_interrupts);
        SOC_CONTROL(unit)->interrupts_info->interrupt_db_info = NULL;
    }

    if (qux_interrupt_tree != NULL) {
        sal_free(qux_interrupt_tree);
        SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info = NULL;
    }

    if(SOC_CONTROL(unit)->interrupts_info != NULL) {
        sal_free(SOC_CONTROL(unit)->interrupts_info);
        SOC_CONTROL(unit)->interrupts_info = NULL;
    }

exit:
    SOCDNX_FUNC_RETURN_VOID;
}

